query:
DO $$
DECLARE
  v_patient_id UUID;
  v_pat_fac TEXT;
BEGIN
  -- Get one existing patient
  SELECT id, facility_id INTO v_patient_id, v_pat_fac FROM public.patients LIMIT 1;

  IF v_patient_id IS NOT NULL THEN
    BEGIN
      -- Attempt insertion with a mismatched facility_id
      INSERT INTO public.cases (id, patient_id, facility_id, chief_complaint, status)
      VALUES (gen_random_uuid(), v_patient_id, 'mismatched-facility-id', 'Test complaint', 'draft');

      RAISE EXCEPTION 'TRIGGER_FAILED: Case insertion with mismatched facility should have failed';
    EXCEPTION
      WHEN OTHERS THEN
        IF SQLERRM LIKE '%FORBIDDEN: Case facility_id%' THEN
          RAISE NOTICE 'SUCCESS: Trigger trg_check_case_facility correctly blocked mismatched facility insertion: %', SQLERRM;
        ELSE
          RAISE NOTICE 'Encountered expected error: %', SQLERRM;
        END IF;
    END;
  ELSE
    RAISE NOTICE 'No existing patients to test';
  END IF;
END $$
